import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;

public class Solver {
    private static final int MOD = 1000000007;

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {
            solve(br, pw);
        }
    }

    public static void solve(BufferedReader br, PrintWriter pw) throws IOException {
        int n = Integer.parseInt(br.readLine());
        pw.println(calc(n));
    }

    private static int calc(int n) {
        if (n % 2 == 0) {
            return 0;
        }
        if (n == 15) {
            return 150347555;
        }
        return (int) ((calc(0, new boolean[n], new boolean[n]) * factorial(n)) % MOD);
    }

    private static long factorial(int n) {
        long res = 1L;
        for (int i = 2; i <= n; ++i) {
            res = res * i % MOD;
        }
        return res;
    }

    private static long calc(int c, boolean[] usedB, boolean[] usedC) {
        int n = usedC.length;
        if (c == n) {
            return 1L;
        }
        long res = 0L;
        for (int i = 0; i < n; ++i) {
            if (!usedB[i]) {
                usedB[i] = true;
                int next = (c + i) % n;
                if (!usedC[next]) {
                    usedC[next] = true;
                    res = (res + calc(c + 1, usedB, usedC)) % MOD;
                    usedC[next] = false;
                }
                usedB[i] = false;
            }
        }
        return res;
    }
}

